import{_ as n,o as i,c as t,a2 as s}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Gesetz zur medizinischen Versorgung","description":"","frontmatter":{},"headers":[],"relativePath":"de/44-医疗保障法.md","filePath":"de/44-医疗保障法.md","lastUpdated":1789183869000}'),r={name:"de/44-医疗保障法.md"};function d(a,e,u,h,l,g){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="gesetz-zur-medizinischen-versorgung" tabindex="-1">Gesetz zur medizinischen Versorgung <a class="header-anchor" href="#gesetz-zur-medizinischen-versorgung" aria-label="Permalink to &quot;Gesetz zur medizinischen Versorgung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>44</td></tr><tr><td>Modul</td><td>Rechtssystem und Governance-Rahmen</td></tr><tr><td>Kernschlüsselwörter</td><td>Medizinrecht, Symbiose-Medizin, Behandlung von Kultivierungsverletzungen, Gesundheit des Lebens, Krankenversicherungssystem</td></tr></tbody></table><h2 id="i-legislatives-ziel-und-grundprinzipien" tabindex="-1">I. Legislatives Ziel und Grundprinzipien <a class="header-anchor" href="#i-legislatives-ziel-und-grundprinzipien" aria-label="Permalink to &quot;I. Legislatives Ziel und Grundprinzipien&quot;">​</a></h2><p>Das 《Gesetz zur medizinischen Versorgung》 ist eines der fünf ergänzenden Gesetze der Anker-Symbiose-Zivilisation. Es zielt darauf ab, das Recht auf Gesundheit und das medizinische Recht aller Wesen innerhalb von Hengyuanzhou zu gewährleisten, ein symbiotisches medizinisches System aufzubauen, das alle Rassen abdeckt, und sicherzustellen, dass jedes Wesen bei Krankheit oder Verletzung eine rechtzeitige und wirksame Behandlung erhalten kann.</p><p>Dieses Gesetz legt folgende Grundprinzipien fest:</p><table tabindex="0"><thead><tr><th>Prinzip</th><th>Inhalt</th></tr></thead><tbody><tr><td>Prinzip der Priorität der Gesundheit</td><td>Die Gesundheit des Lebens ist die Grundlage aller Evolution, Staat und Zivilisation stellen die Gewährleistung der Gesundheit des Lebens an erste Stelle</td></tr><tr><td>Prinzip der universellen Abdeckung</td><td>Die medizinische Versorgung deckt alle Wesen ab, unabhängig von Rasse, Kultivierungsniveau, Herkunft und wirtschaftlicher Situation</td></tr><tr><td>Prinzip der gestuften Diagnostik</td><td>Aufbau eines dreistufigen Diagnosesystems: Primärversorgung, regionale Medizin, fortgeschrittene Medizin, rationelle Verteilung der medizinischen Ressourcen</td></tr><tr><td>Prinzip der Kombination von Prävention und Behandlung</td><td>Prävention als Hauptsache, Kombination von Prävention und Behandlung, Wertlegung auf Prävention und Rehabilitation von Kultivierungsverletzungen</td></tr><tr><td>Prinzip der interrassischen Anpassung</td><td>Bereitstellung angepasster medizinischer Pläne entsprechend den physiologischen Merkmalen verschiedener Rassen, Verbot der einheitlichen Anwendung menschlicher Standards</td></tr><tr><td>Prinzip des Gemeinwohlcharakters</td><td>Grundlegende medizinische Dienstleistungen haben Gemeinwohlcharakter, das Recht auf Behandlung des Lebens darf nicht aus Profitgründen entzogen werden</td></tr></tbody></table><h2 id="ii-rechtliche-gewahrleistung-des-rechts-auf-gesundheit-des-lebens" tabindex="-1">II. Rechtliche Gewährleistung des Rechts auf Gesundheit des Lebens <a class="header-anchor" href="#ii-rechtliche-gewahrleistung-des-rechts-auf-gesundheit-des-lebens" aria-label="Permalink to &quot;II. Rechtliche Gewährleistung des Rechts auf Gesundheit des Lebens&quot;">​</a></h2><p>Dieses Gesetz legt klar fest, dass das Recht auf Gesundheit des Lebens ein Grundrecht ist, das jedem Wesen durch die Symbiose-Verfassung gewährt wird, und umfasst konkret:</p><ol><li><strong>Grundlegendes medizinisches Recht</strong>: Jedes Wesen hat das Recht auf kostenlose grundlegende medizinische Dienstleistungen, einschließlich Diagnose und Behandlung von Volkskrankheiten, Grundmedikamente, regelmäßige Gesundheitsuntersuchungen usw.</li><li><strong>Recht auf Notfallbehandlung</strong>: Jedes Wesen hat bei plötzlicher Krankheit oder Verletzung das Recht auf Notfallbehandlung, und medizinische Einrichtungen dürfen die Notfallbehandlung aus keinem Grund ablehnen.</li><li><strong>Recht auf Behandlung von Kultivierungsverletzungen</strong>: Kultivierer, die während des Kultivierungsprozesses Verletzungen wie Energiestörungen, Meridianverletzungen, Kultivierungsabweichungen usw. erleiden, haben das Recht auf professionelle Behandlung.</li><li><strong>Recht auf informierte Einwilligung</strong>: Der Patient hat das Recht, seinen eigenen Zustand, den Behandlungsplan, die Risiken und die Prognose zu kennen, und hat das Recht, den Behandlungsplan zu wählen oder abzulehnen.</li><li><strong>Recht auf Datenschutz</strong>: Die medizinischen Informationen und Körperschaftsdaten des Patienten sind gesetzlich geschützt und dürfen ohne Zustimmung des Patienten nicht offengelegt oder für andere Zwecke verwendet werden.</li><li><strong>Recht auf Rehabilitationsgarantie</strong>: Kranke oder verletzte Patienten haben das Recht auf Rehabilitationsbehandlung und Hilfsmittel, die ihnen bei der Wiederherstellung der Arbeits- und Lebensfähigkeit helfen.</li></ol><h2 id="iii-struktur-des-symbiotischen-medizinischen-systems" tabindex="-1">III. Struktur des symbiotischen medizinischen Systems <a class="header-anchor" href="#iii-struktur-des-symbiotischen-medizinischen-systems" aria-label="Permalink to &quot;III. Struktur des symbiotischen medizinischen Systems&quot;">​</a></h2><p>Das medizinische System der Anker-Symbiose-Zivilisation ist in drei Ebenen unterteilt, zwischen denen Überweisungs- und Kooperationsmechanismen eingerichtet wurden:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Name</th><th>Funktion</th><th>Abdeckungsbereich</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Primäre Gesundheitsstation</td><td>Diagnose und Behandlung von Volkskrankheiten, Prävention und Gesundheitsfürsorge, Grunduntersuchungen, Notfalltransport</td><td>Gemeinschaft/Dorf/kleine Ebene</td></tr><tr><td>Zweite Ebene</td><td>Regionales medizinisches Zentrum</td><td>Fachdiagnostik, chirurgische Behandlung, Erstbehandlung von Kultivierungsverletzungen, Rehabilitation</td><td>Stadt/Region/mittlere Ebene</td></tr><tr><td>Dritte Ebene</td><td>Zentrales medizinisches Krankenhaus</td><td>Schwere und komplexe Krankheiten, fortgeschrittene Kultivierungsverletzungen, Bewusstseinsdomänen-Krankheiten, interrassische komplexe Krankheiten</td><td>Zivilisationskern/große Ebene</td></tr></tbody></table><p>Darüber hinaus wurde die &quot;Fachabteilung für Kultivierungsverletzungen&quot; eingerichtet: Sie behandelt speziell verschiedene Arten von Verletzungen während des Kultivierungsprozesses, einschließlich Energieüberlastung, Meridianbrüche, Eindringen von inneren Dämonen, Seelentrauma usw., und ist mit medizinischem Personal ausgestattet, das die Kultivierungsgesetze beherrscht.</p><h2 id="iv-fonds-fur-medizinische-versorgung" tabindex="-1">IV. Fonds für medizinische Versorgung <a class="header-anchor" href="#iv-fonds-fur-medizinische-versorgung" aria-label="Permalink to &quot;IV. Fonds für medizinische Versorgung&quot;">​</a></h2><p>Der Fonds für medizinische Versorgung ist die wirtschaftliche Grundlage für den Betrieb des symbiotischen medizinischen Systems, und seine Quellen umfassen:</p><ul><li>Zuweisung aus öffentlicher Rücklage (Hauptquelle)</li><li>Einbehaltung für medizinische Versorgung im Mechanismus des gemeinsamen Produktionsvertrags</li><li>Sozialspenden</li><li>Anlageerträge des Fonds</li></ul><p>Der Zahlungsumfang des Fonds umfasst: Kosten für grundlegende medizinische Dienstleistungen, Notfallkosten, Kosten für die Behandlung von Kultivierungsverletzungen, Kosten für Grundmedikamente, Rehabilitationskosten usw. Der einzelne Patient muss nur eine geringe Selbstbeteiligung zahlen, und für Personen mit wirtschaftlichen Schwierigkeiten werden Befreiungen gewährt.</p><h2 id="v-medizinische-einrichtungen-und-medizinisches-personal" tabindex="-1">V. Medizinische Einrichtungen und medizinisches Personal <a class="header-anchor" href="#v-medizinische-einrichtungen-und-medizinisches-personal" aria-label="Permalink to &quot;V. Medizinische Einrichtungen und medizinisches Personal&quot;">​</a></h2><ul><li><strong>Öffentliche medizinische Einrichtungen</strong>: Vom Staat oder der Zivilisationsgemeinschaft gegründet, verantwortlich für grundlegende medizinische Dienstleistungen und Funktionen der öffentlichen Gesundheit, die Finanzierung wird durch den Fonds für medizinische Versorgung gewährleistet.</li><li><strong>Private medizinische Einrichtungen</strong>: Von gesellschaftlichen Kräften nach Gesetz gegründet, können hochwertige medizinische Dienstleistungen anbieten, müssen aber die Aufsicht durch die zuständige Gesundheitsbehörde akzeptieren und dürfen Notfallpatienten nicht ablehnen.</li><li><strong>Interrassische medizinische Einrichtungen</strong>: Spezialisierte medizinische Einrichtungen, die für die physiologischen Bedürfnisse besonderer Rassen eingerichtet wurden, ausgestattet mit medizinischem Personal anderer Rassen.</li><li><strong>Rechte und Pflichten des medizinischen Personals</strong>: Das medizinische Personal genießt Rechte wie Berufsschutz, angemessene Vergütung, berufliche Ausbildung usw., und hat gleichzeitig die Pflicht, Leben zu retten, Patienten zu respektieren, das medizinische Geheimnis zu wahren usw.</li></ul><h2 id="vi-offentliche-gesundheit-und-pravention" tabindex="-1">VI. Öffentliche Gesundheit und Prävention <a class="header-anchor" href="#vi-offentliche-gesundheit-und-pravention" aria-label="Permalink to &quot;VI. Öffentliche Gesundheit und Prävention&quot;">​</a></h2><p>Der Staat baut ein System der öffentlichen Gesundheit auf und erfüllt folgende Funktionen:</p><ol><li>Überwachung sowie Prävention und Kontrolle von Infektionskrankheiten, Einrichtung eines Mechanismus zur Epidemiewarnung zwischen Ebenen.</li><li>Allgemeine Gesundheitsuntersuchungen und Verwaltung von Gesundheitsakten.</li><li>Förderung der Kultivierungssicherheit und Anleitung zur Prävention von Kultivierungsverletzungen.</li><li>Aufsicht über Umwelthygiene sowie Lebensmittel- und Arzneimittelsicherheit.</li><li>Notfallreaktion auf plötzliche Ereignisse der öffentlichen Gesundheit.</li></ol><h2 id="vii-rechtliche-verantwortung" tabindex="-1">VII. Rechtliche Verantwortung <a class="header-anchor" href="#vii-rechtliche-verantwortung" aria-label="Permalink to &quot;VII. Rechtliche Verantwortung&quot;">​</a></h2><p>Handlungen, die gegen die Bestimmungen dieses Gesetzes verstoßen, tragen je nach Schwere des Verstoßes folgende Verantwortung:</p><ul><li>Medizinische Einrichtungen, die Notfallpatienten ablehnen, werden zur Korrektur angehalten und mit einer Geldbuße belegt, in Fällen schwerer Folgen wird die Berufserlaubnis entzogen.</li><li>Medizinisches Personal, das durch grobe Fahrlässigkeit Schaden am Patienten verursacht, trägt Schadensersatzverantwortung, in schweren Fällen wird die Berufsqualifikation entzogen.</li><li>Medizinische Einrichtungen, die rechtswidrig Gebühren erheben oder Überbehandlung durchführen, werden zur Rückerstattung der Gebühren angehalten und mit einer Geldbuße belegt.</li><li>Offenlegung der medizinischen Privatsphäre eines Patienten, Übernahme von Schmerzensgeld, in schweren Fällen strafrechtliche Verfolgung.</li><li>Herstellung oder Verkauf von gefälschten oder minderwertigen Arzneimitteln, Einziehung der rechtswidrigen Erträge und Geldbuße, bei Straftat strafrechtliche Verfolgung.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das 《Gesetz zur medizinischen Versorgung》 ist die Verkörperung des Konzepts &quot;jeder hat einen Weg&quot; der Anker-Symbiose-Zivilisation im Gesundheitsbereich. Durch den Aufbau eines universell abgedeckten medizinischen Versorgungssystems, die Einrichtung der Fachabteilung für Kultivierungsverletzungen und die Gewährleistung des Rechts auf Notfallbehandlung stellt es sicher, dass jedes Wesen bei Krankheit oder Verletzung eine rechtzeitige Behandlung erhalten kann, und festigt die Gesundheitsgrundlage für den gemeinsamen Fortschritt aller Rassen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Allgemeine Grundsätze der Symbiose-Verfassung)</li><li>38-共生医疗体系 (Symbiose-medizinisches System)</li><li>45-住房保障法 (Gesetz zur Wohnungsgarantie)</li><li>08-人人有路保障体系 (Garantiesystem, dass jeder einen Weg hat)</li></ul>',29)])])}const m=n(r,[["render",d]]);export{c as __pageData,m as default};
